#include <string>
#include <vector>

class RecentLog
{
public:
    explicit RecentLog(std::size_t capacity) : m_slots(capacity) {}

    void add(std::string line)
    {
        m_slots[m_next] = std::move(line);
        m_next = (m_next + 1) % m_slots.size();
        if (m_count < m_slots.size()) ++m_count;
        else ++m_dropped;
    }

    std::vector<std::string> lines() const
    {
        std::vector<std::string> out;
        out.reserve(m_count);
        const std::size_t oldest{ (m_next + m_slots.size() - m_count) % m_slots.size() };
        for (std::size_t i{ 0 }; i < m_count; ++i)
            out.push_back(m_slots[(oldest + i) % m_slots.size()]);
        return out;
    }

    std::size_t size() const { return m_count; }
    std::size_t dropped() const { return m_dropped; }

private:
    std::vector<std::string> m_slots;
    std::size_t m_next{ 0 };
    std::size_t m_count{ 0 };
    std::size_t m_dropped{ 0 };
};

unitTests:
using L = std::vector<std::string>;
TEST("not yet full") { RecentLog log{ 3 }; log.add("a"); log.add("b"); CHECK(log.lines() == L({ "a", "b" })); CHECK_EQ(log.size(), std::size_t{ 2 }); CHECK_EQ(log.dropped(), std::size_t{ 0 }); }
TEST("the example") { RecentLog log{ 3 }; for (const char* s : { "a", "b", "c", "d" }) log.add(s); CHECK(log.lines() == L({ "b", "c", "d" })); CHECK_EQ(log.dropped(), std::size_t{ 1 }); }
TEST("wrapping several times") { RecentLog log{ 3 }; for (int i{ 0 }; i < 10; ++i) log.add(std::to_string(i)); CHECK(log.lines() == L({ "7", "8", "9" })); CHECK_EQ(log.dropped(), std::size_t{ 7 }); CHECK_EQ(log.size(), std::size_t{ 3 }); }
TEST("capacity one") { RecentLog log{ 1 }; log.add("x"); log.add("y"); CHECK(log.lines() == L({ "y" })); }
TEST("empty") { RecentLog log{ 4 }; CHECK(log.lines().empty()); CHECK_EQ(log.size(), std::size_t{ 0 }); }
TEST("exactly full") { RecentLog log{ 2 }; log.add("p"); log.add("q"); CHECK(log.lines() == L({ "p", "q" })); CHECK_EQ(log.dropped(), std::size_t{ 0 }); }

